<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,watch,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Icon from './components/Icon.vue'
import EventDrawer from './components/EventDrawer.vue'
import {state,t,fmt,russianAvailable,setLocale,setTheme,bootstrap,loadData,api,wp,loadWorkspaces,switchWorkspace,roles,activeJob,notify} from './state'
const route=useRoute(),router=useRouter(),dismissed=ref('')
const publicPaths=['/','/login','/register','/verify','/reset','/invite','/control']
const product=computed(()=>!publicPaths.includes(route.path)&&state.user&&state.workspace?.onboarded&&route.path!='/onboarding')
const nav=computed(()=>[{path:'/overview',icon:'LayoutDashboard',label:t('Overview','Обзор')},{path:'/events',icon:'Radar',label:t('Business signals','Бизнес-сигналы'),count:state.events.length},{path:'/briefs',icon:'FileChartColumn',label:t('Executive briefs','Сводки')},{path:'/assistant',icon:'Sparkles',label:t('Ask SignalDesk','Спросить SignalDesk')},{path:'/sources',icon:'Radio',label:t('Sources & monitoring','Источники и мониторинг')},{path:'/company',icon:'Building2',label:t('Company context','Контекст компании')},{path:'/settings',icon:'Settings2',label:t('Workspace settings','Настройки пространства')}])
const unread=computed(()=>state.alerts.filter(a=>!a.read).length)
const failed=computed(()=>state.jobs.find(j=>j.status==='failed'&&j.id!==dismissed.value))
let poll:any,counter=0
function guard(){if(!state.ready||publicPaths.includes(route.path))return;if(!state.user)router.replace('/login');else if(!state.workspace?.onboarded&&route.path!='/onboarding')router.replace('/onboarding')}
watch(()=>[route.path,state.ready,state.user?.id,state.workspace?.id],()=>{guard();state.mobileNav=false})
async function changeWorkspace(e:Event){const id=(e.target as HTMLSelectElement).value;if(id==='new'){router.push('/onboarding?new=1');return}await switchWorkspace(id);router.push(state.workspace.onboarded?'/overview':'/onboarding')}
async function changeRole(e:Event){try{state.workspace=await api(wp('/decision-role'),{method:'PATCH',body:{role:(e.target as HTMLSelectElement).value}});await loadWorkspaces(state.workspace.id);await loadData();notify(t('Your view now reflects this decision role. Run monitoring to prepare new role-specific insights.','Представление настроено под вашу роль. Запустите мониторинг для новой персональной аналитики.'))}catch(err:any){notify(err.message,true)}}
async function logout(){await api('/auth/logout',{method:'POST'});state.user=null;state.workspace=null;state.events=[];router.push('/')}
async function tick(){if(!state.workspace)return;counter++;try{if(activeJob.value){const previous=state.jobs;const next=await api(wp('/jobs'));state.jobs=next;const completed=next.some((j:any)=>j.status==='completed'&&previous.some(p=>p.id===j.id&&p.status!=='completed'));if(completed){await loadWorkspaces(state.workspace.id);await loadData()}}else if(counter%10===0&&state.workspace.onboarded){state.alerts=await api(wp('/alerts'))}}catch{}}
onMounted(async()=>{await bootstrap();guard();poll=setInterval(tick,3000)})
onBeforeUnmount(()=>clearInterval(poll))
</script>
<template>
<div v-if="!state.ready" class="app-loading"><div class="brand"><span class="brand-symbol"><Icon name="AudioLines" :size="23"/></span>SignalDesk</div><div class="loading-line"></div></div>
<template v-else>
<div v-if="product" class="app-layout">
  <div v-if="state.mobileNav" class="nav-backdrop" @click="state.mobileNav=false"></div>
  <aside class="sidebar" :class="{open:state.mobileNav}"><RouterLink to="/overview" class="brand"><span class="brand-symbol"><Icon name="AudioLines" :size="23"/></span>SignalDesk<span class="brand-dot"></span></RouterLink>
    <label class="workspace-switch"><span class="workspace-avatar">{{state.workspace.name.slice(0,1)}}</span><span class="workspace-switch-body"><span class="tiny muted">{{t('WORKSPACE','ПРОСТРАНСТВО')}}</span><select :value="state.workspace.id" @change="changeWorkspace" :aria-label="t('Switch workspace','Сменить пространство')"><option v-for="w in state.workspaces" :value="w.id" :key="w.id">{{w.name}}</option><option value="new">＋ {{t('New workspace','Новое пространство')}}</option></select></span><Icon name="ChevronsUpDown" :size="15"/></label>
    <span class="nav-label">{{t('INTELLIGENCE','АНАЛИТИКА')}}</span><nav aria-label="Main navigation"><RouterLink v-for="(n,i) in nav" :key="n.path" :to="n.path" class="nav-item" :class="{'nav-separated':i===4}"><Icon :name="n.icon" :size="19"/><span>{{n.label}}</span><span v-if="n.count" class="nav-count">{{n.count}}</span></RouterLink></nav>
    <div class="sidebar-bottom"><div class="research-promo"><span class="research-promo-icon"><Icon name="BookOpen" :size="19"/></span><h4>{{t('A perspective you can trace','Выводы с основаниями')}}</h4><p>{{t('Every insight starts with evidence. Explore the research behind it.','За каждым выводом — источники. Изучите аналитику, на которой он основан.')}}</p><RouterLink to="/sources?tab=research" class="text-link">{{t('Research library','Библиотека аналитики')}}<Icon name="ArrowUpRight" :size="14"/></RouterLink></div>
    <button class="user-menu" @click="router.push('/settings?tab=profile')"><span class="avatar">{{state.user.name.slice(0,1)}}</span><span><strong>{{state.user.name}}</strong><small>{{t({owner:'Workspace owner',admin:'Administrator',analyst:'Analyst',viewer:'Viewer'}[state.workspace.role],{owner:'Владелец пространства',admin:'Администратор',analyst:'Аналитик',viewer:'Наблюдатель'}[state.workspace.role])}}</small></span><Icon name="Settings" :size="16"/></button></div>
  </aside>
  <main class="main-area"><header class="topbar"><div class="row gap-sm"><button class="icon-btn mobile-only" @click="state.mobileNav=true" :aria-label="t('Open navigation','Открыть меню')"><Icon name="Menu"/></button><span class="breadcrumb">{{state.workspace.name}}<Icon name="ChevronRight" :size="13"/><strong>{{nav.find(n=>n.path===route.path)?.label}}</strong></span></div><div class="top-actions"><span class="today"><Icon name="CalendarDays" :size="15"/>{{fmt(new Date().toISOString(),{month:'short',day:'numeric',year:'numeric'})}}</span><button v-if="russianAvailable" class="language-btn" @click="setLocale">{{state.locale==='ru'?'EN':'RU'}}</button><button class="icon-btn" @click="setTheme" :aria-label="t('Toggle appearance','Переключить тему')"><Icon :name="state.theme==='dark'?'Sun':'Moon'" :size="17"/></button><RouterLink to="/events?alerts=1" class="icon-btn notification-bell" :aria-label="t('Notifications','Уведомления')"><Icon name="Bell" :size="18"/><i v-if="unread"></i></RouterLink></div></header>
  <div v-if="state.workspace.demo" class="demo-banner"><Icon name="FlaskConical" :size="16"/><span>{{t('Demo workspace · Events and company exposures are synthetic. Bank research is from the case.','Демо · События и данные компании учебные. Обзоры банка — из материалов кейса.')}}</span><RouterLink to="/onboarding?new=1">{{t('Add your company','Добавить компанию')}}<Icon name="ArrowRight" :size="14"/></RouterLink></div>
  <div class="page-content"><div class="view-role"><span class="live-dot"></span><span>{{t('PERSONALISED FOR','ПЕРСОНАЛЬНО ДЛЯ')}}</span><select :value="state.workspace.decision_role" @change="changeRole" :aria-label="t('Your decision role','Ваша бизнес-роль')"><option v-for="r in roles" :value="r.id" :key="r.id">{{r.label}}</option></select></div>
  <div v-if="activeJob" class="job-banner" role="status"><Icon name="LoaderCircle" class="spin" :size="19"/><div><strong>{{t('Preparing your intelligence','Готовим вашу аналитику')}}</strong><span>{{activeJob.steps?.at(-1)?.name?.replaceAll('_',' ')||t('Waiting to start','Ожидание запуска')}} · {{activeJob.progress}}%</span></div><div class="progress-track"><i :style="{width:Math.max(4,activeJob.progress)+'%'}"></i></div><RouterLink to="/sources?tab=runs">{{t('View run','Ход анализа')}}<Icon name="ArrowUpRight" :size="14"/></RouterLink></div>
  <div v-else-if="failed" class="notice error-notice" role="alert"><Icon name="AlertCircle" :size="18"/><div><strong>{{t('A run needs attention','Анализ требует внимания')}}</strong><p>{{failed.error}}</p></div><RouterLink to="/sources?tab=runs" class="text-link">{{t('Review','Подробнее')}}</RouterLink><button class="icon-btn" @click="dismissed=failed.id" :aria-label="t('Dismiss','Скрыть')"><Icon name="X" :size="16"/></button></div>
  <RouterView :key="state.workspace.id+route.path"/></div><footer class="app-footer"><span>SignalDesk <span class="muted">/</span> {{t('A clearer view of what matters.','Ясный взгляд на то, что важно.')}}</span><span class="row gap-sm"><span class="live-dot"></span>{{t('Evidence, then insight','Сначала источники, затем выводы')}}</span></footer></main>
</div>
<div v-else :class="{'public-app':route.path!='/control'}"><header v-if="route.path!='/control'" class="public-header"><RouterLink to="/" class="brand"><span class="brand-symbol"><Icon name="AudioLines" :size="23"/></span>SignalDesk<span class="brand-dot"></span></RouterLink><div class="row gap-sm"><button v-if="russianAvailable" class="language-btn" @click="setLocale">{{state.locale==='ru'?'EN':'RU'}}</button><button class="icon-btn" @click="setTheme" :aria-label="t('Toggle appearance','Переключить тему')"><Icon :name="state.theme==='dark'?'Sun':'Moon'" :size="18"/></button><button v-if="state.user" class="btn ghost small-btn" @click="logout">{{t('Sign out','Выйти')}}</button><RouterLink v-else to="/login" class="btn ghost">{{t('Sign in','Войти')}}<Icon name="ArrowUpRight" :size="15"/></RouterLink></div></header><RouterView/></div>
<EventDrawer/>
<Transition name="toast"><div v-if="state.toast" class="toast" :class="{error:state.toastError}" role="alert"><Icon :name="state.toastError?'AlertCircle':'CheckCircle2'" :size="19"/><span>{{state.toast}}</span><button class="icon-btn" @click="state.toast=''" :aria-label="t('Dismiss notification','Закрыть уведомление')"><Icon name="X" :size="15"/></button></div></Transition>
</template>
</template>
